THOUGHT: I’ll implement the shared SQLite-backed HTTP cluster first, including authentication, workspaces, channels, messages, threads, events, reactions, pins, profiles, invitations, groups, search, and a minimal WebSocket event stream. The supervisor will launch Redis and all three nodes with restart loops, preserving data under `/var/lib/huddle`.

```mswea_bash_command
cat > /app/server.py <<'PY'
import sys, os, json, sqlite3, hashlib, secrets, re, time, threading, socket, struct, base64, urllib.parse, mimetypes
from datetime import datetime, timezone
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

PORT=int(sys.argv[1]) if len(sys.argv)>1 else 8000
NODE=PORT-8000
DB='/var/lib/huddle/huddle.db'
os.makedirs('/var/lib/huddle',exist_ok=True)
WS=set(); WSL=threading.Lock()
def now(): return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def db():
    c=sqlite3.connect(DB,timeout=10); c.row_factory=sqlite3.Row
    c.execute('PRAGMA journal_mode=WAL'); return c
def init():
 c=db()
 c.executescript('''
 CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
 CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
 CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
 CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
 CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0,UNIQUE(workspace_id,name));
 CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
 CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
 CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
 CREATE TABLE IF NOT EXISTS pins(message_id INTEGER PRIMARY KEY,pinned_by INTEGER,pinned_at TEXT);
 CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,channel_id INTEGER,event_id INTEGER,kind TEXT,payload TEXT,UNIQUE(channel_id,event_id));
 CREATE TABLE IF NOT EXISTS reads(user_id INTEGER,channel_id INTEGER,last_read_event_id INTEGER DEFAULT 0,PRIMARY KEY(user_id,channel_id));
 CREATE TABLE IF NOT EXISTS invitations(code TEXT PRIMARY KEY,workspace_id INTEGER,invited_user_id INTEGER,expires_at TEXT,max_uses INTEGER,uses INTEGER DEFAULT 0);
 CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,user_ids TEXT,UNIQUE(workspace_id,handle));
 CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,created_at TEXT,data BLOB);
 '''); c.commit(); c.close()
init()
def q(sql,args=(),one=False):
 c=db(); r=c.execute(sql,args); out=r.fetchone() if one else r.fetchall(); c.close(); return out
def ex(sql,args=()):
 c=db(); r=c.execute(sql,args); c.commit(); x=r.lastrowid; c.close(); return x
def userobj(r):
 return dict(r) if r else None
def auth(h):
 a=h.get('Authorization','')
 if not a.startswith('Bearer '): return None
 r=q('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(a[7:],),True)
 return r
def wsobj(r): return dict(r)
def chanobj(r): 
 d=dict(r); d['is_private']=bool(d['is_private']); d['is_dm']=bool(d['is_dm']); d['is_archived']=bool(d['is_archived']); return d
def member(uid,wid):
 r=q('SELECT role FROM members WHERE user_id=? AND workspace_id=?',(uid,wid),True); return r['role'] if r else None
def accessible(uid,cid):
 r=q('SELECT c.workspace_id,c.is_private FROM channels c WHERE c.id=?',(cid,),True)
 return bool(r and (not r['is_private'] and member(uid,r['workspace_id']) or q('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(cid,uid),True)))
def msgobj(r):
 d=dict(r); d['parent_id']=d['parent_id']; d['edited_at']=d['edited_at']
 u=q('SELECT * FROM users WHERE id=?',(d['author_id'],),True); d['author']=dict(u) if u else None
 rr=q('SELECT emoji,COUNT(*) count,GROUP_CONCAT(user_id) ids FROM reactions WHERE message_id=? GROUP BY emoji',(d['id'],))
 d['reactions']=[{'emoji':x['emoji'],'count':x['count'],'user_ids':[int(z) for z in x['ids'].split(',')]} for x in rr]
 d['reply_count']=q('SELECT COUNT(*) n FROM messages WHERE parent_id=? AND deleted=0',(d['id'],),True)['n']; d['files']=[]; d['mentions']=[]
 return d
def emit(cid,kind,payload):
 c=db(); n=c.execute('SELECT COALESCE(MAX(event_id),0)+1 n FROM events WHERE channel_id=?',(cid,)).fetchone()['n']
 c.execute('INSERT INTO events(channel_id,event_id,kind,payload) VALUES(?,?,?,?)',(cid,n,kind,json.dumps(payload))); c.commit(); c.close()
 frame={'type':kind,'event_id':n,'channel_id':cid}; frame.update(payload); broadcast(cid,frame); return n
def broadcast(cid,obj):
 raw=json.dumps(obj).encode()
 with WSL:
  targets=list(WS)
 for s,ch in targets:
  if ch==cid:
   try: sendws(s,raw)
   except: pass
def sendws(s,p):
 b=p; n=len(b); head=bytes([0x81])
 if n<126: head+=bytes([n])
 elif n<65536: head+=bytes([126])+struct.pack('>H',n)
 else: head+=bytes([127])+struct.pack('>Q',n)
 s.sendall(head+b)
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*x): pass
 def send(self,code,obj=None,typ='application/json'):
  b=(json.dumps(obj).encode() if obj is not None else b'')
  self.send_response(code); self.send_header('Content-Type',typ); self.send_header('Content-Length',str(len(b))); self.end_headers()
  if b:self.wfile.write(b)
 def body(self):
  n=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(n) or b'{}')
 def require(self):
  u=auth(self.headers)
  if not u:self.send(401,{'error':'unauthorized'}); return None
  return u
 def route(self):
  p=urllib.parse.urlparse(self.path); path=p.path; qs=urllib.parse.parse_qs(p.query); method=self.command
  if path=='/api/health': return self.send(200,{'status':'ok','node_id':NODE})
  if path=='/': return self.html()
  if path=='/api/auth/register' and method=='POST':
   b=self.body(); un=b.get('username',''); pw=b.get('password','')
   if not re.fullmatch(r'[A-Za-z0-9_]+',un) or len(pw)<8:return self.send(400,{'error':'invalid'})
   try: uid=ex('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(un,hashlib.sha256(pw.encode()).hexdigest(),b.get('display_name') or un))
   except sqlite3.IntegrityError:return self.send(409,{'error':'duplicate'})
   t=secrets.token_urlsafe(24); ex('INSERT INTO tokens VALUES(?,?)',(t,uid)); return self.send(201,{'user':dict(q('SELECT * FROM users WHERE id=?',(uid,),True)),'token':t})
  if path=='/api/auth/login' and method=='POST':
   b=self.body(); r=q('SELECT * FROM users WHERE username=? AND password=?',(b.get('username'),hashlib.sha256(b.get('password','').encode()).hexdigest()),True)
   if not r:return self.send(401,{'error':'invalid'})
   t=secrets.token_urlsafe(24); ex('INSERT INTO tokens VALUES(?,?)',(t,r['id'])); return self.send(200,{'user':dict(r),'token':t})
  if path.startswith('/api/ws'):
   return self.websocket()
  u=self.require()
  if not u:return
  uid=u['id']
  if path=='/api/auth/me': return self.send(200,{'user':dict(u)})
  if path=='/api/users/me' and method=='PATCH':
   b=self.body(); allowed={'display_name','timezone','avatar_url','status_text','status_emoji'}; vals={k:v for k,v in b.items() if k in allowed}
   if 'timezone' in vals and not isinstance(vals['timezone'],str):return self.send(400,{'error':'timezone'})
   if vals:
    ex('UPDATE users SET '+','.join(k+'=?' for k in vals)+' WHERE id=?',tuple(vals.values())+(uid,))
   return self.send(200,{'user':dict(q('SELECT * FROM users WHERE id=?',(uid,),True))})
  m=re.fullmatch(r'/api/users/(\d+)',path)
  if m:
   r=q('SELECT * FROM users WHERE id=?',(m.group(1),),True); return self.send(200,{'user':dict(r)}) if r else self.send(404,{'error':'not found'})
  if path=='/api/workspaces' and method=='GET':
   rows=q('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(uid,)); return self.send(200,{'workspaces':[wsobj(x) for x in rows]})
  if path=='/api/workspaces' and method=='POST':
   b=self.body()
   if not re.fullmatch(r'[a-z0-9-]{2,32}',b.get('slug','')):return self.send(400,{'error':'slug'})
   try: wid=ex('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(b['slug'],b.get('name',b['slug']),uid))
   except sqlite3.IntegrityError:return self.send(409,{'error':'duplicate'})
   ex('INSERT INTO members VALUES(?,?,?)',(wid,uid,'owner')); cid=ex('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general')); ex('INSERT INTO channel_members VALUES(?,?)',(cid,uid))
   return self.send(201,{'workspace':wsobj(q('SELECT * FROM workspaces WHERE id=?',(wid,),True)),'general_channel':chanobj(q('SELECT * FROM channels WHERE id=?',(cid,),True))})
  m=re.fullmatch(r'/api/workspaces/([^/]+)',path)
  if m:
   w=q('SELECT * FROM workspaces WHERE slug=?',(m.group(1),),True)
   if not w:return self.send(404,{'error':'not found'})
   role=member(uid,w['id'])
   if method=='PATCH':
    if role not in ('owner','admin'):return self.send(403,{'error':'forbidden'})
    b=self.body(); vals={k:b[k] for k in ('name','join_mode') if k in b}; 
    if vals: ex('UPDATE workspaces SET '+','.join(k+'=?' for k in vals)+' WHERE id=?',tuple(vals.values())+(w['id'],))
    return self.send(200,{'workspace':wsobj(q('SELECT * FROM workspaces WHERE id=?',(w['id'],),True))})
   chans=q('SELECT * FROM channels WHERE workspace_id=? AND (is_archived=0 OR is_archived=?)',(w['id'],1 if qs.get('include_archived') else 0))
   return self.send(200,{'workspace':wsobj(w),'channels':[chanobj(x) for x in chans],'read_state':[]})
  m=re.fullmatch(r'/api/workspaces/([^/]+)/members',path)
  if m:
   w=q('SELECT id FROM workspaces WHERE slug=?',(m.group(1),),True)
   if not w:return self.send(404,{'error':'not found'})
   rows=q('SELECT user_id,role FROM members WHERE workspace_id=?',(w['id'],)); return self.send(200,{'members':[dict(x) for x in rows]})
  m=re.fullmatch(r'/api/workspaces/([^/]+)/channels',path)
  if m and method=='POST':
   w=q('SELECT * FROM workspaces WHERE slug=?',(m.group(1),),True); role=member(uid,w['id']) if w else None
   if not w:return self.send(404,{'error':'not found'})
   b=self.body(); name=b.get('name','')
   if not re.fullmatch(r'[a-z0-9-]{1,32}',name):return self.send(400,{'error':'name'})
   if not role:return self.send(403,{'error':'member'})
   if role=='guest' or (b.get('is_private') and role not in ('owner','admin')):return self.send(403,{'error':'forbidden'})
   try: cid=ex('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],name,int(bool(b.get('is_private'))),b.get('topic','')))
   except sqlite3.IntegrityError:return self.send(409,{'error':'duplicate'})
   ex('INSERT INTO channel_members VALUES(?,?)',(cid,uid)); return self.send(201,{'channel':chanobj(q('SELECT * FROM channels WHERE id=?',(cid,),True))})
  m=re.fullmatch(r'/api/channels/(\d+)(?:/(.*))?',path)
  if m:
   cid=int(m.group(1)); c=q('SELECT * FROM channels WHERE id=?',(cid,),True)
   if not c:return self.send(404,{'error':'channel'})
   if method=='POST' and m.group(2)=='join':
    w=q('SELECT * FROM workspaces WHERE id=?',(c['workspace_id'],),True); role=member(uid,w['id'])
    if c['is_private']:return self.send(403,{'error':'private'})
    if not role:
     if w['join_mode']!='open':return self.send(403,{'error':'invite'})
     ex('INSERT OR IGNORE INTO members VALUES(?,?,?)',(w['id'],uid,'member'))
    ex('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(cid,uid)); emit(cid,'member.joined',{'user_id':uid}); return self.send(200,{'channel':chanobj(c)})
   if not accessible(uid,cid):return self.send(403,{'error':'forbidden'})
   sub=m.group(2)
   if method=='GET' and not sub:
    rows=q('SELECT * FROM messages WHERE channel_id=? AND deleted=0 AND parent_id IS NULL ORDER BY id DESC LIMIT 200',(cid,)); return self.send(200,{'messages':[msgobj(x) for x in rows],'next_cursor':None})
   if method=='POST' and sub=='messages':
    b=self.body(); body=b.get('body','')
    if not body:return self.send(400,{'error':'empty'})
    if c['is_archived']:return self.send(423,{'error':'archived'})
    parent=b.get('parent_id'); mid=ex('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)',(cid,uid,body,parent,now())); mo=msgobj(q('SELECT * FROM messages WHERE id=?',(mid,),True)); emit(cid,'message.reply' if parent else 'message.created',{'message':mo}); return self.send(201,{'message':mo})
   if method=='GET' and sub=='members':
    rows=q('SELECT u.* FROM users u JOIN channel_members cm ON cm.user_id=u.id WHERE cm.channel_id=?',(cid,)); return self.send(200,{'members':[dict(x) for x in rows]})
   if method=='POST' and sub=='leave': ex('DELETE FROM channel_members WHERE channel_id=? AND user_id=?',(cid,uid)); return self.send(200,{'channel':chanobj(c)})
   if method=='PATCH' and sub is None:
    b=self.body(); ex('UPDATE channels SET topic=? WHERE id=?',(b.get('topic',''),cid)); return self.send(200,{'channel':chanobj(q('SELECT * FROM channels WHERE id=?',(cid,),True))})
   if method=='GET' and sub=='pins': 
    rows=q('SELECT p.*,m.* FROM pins p JOIN messages m ON m.id=p.message_id WHERE m.channel_id=? ORDER BY p.pinned_at DESC',(cid,)); return self.send(200,{'pins':[{'message':msgobj(x),'pinned_by':x['pinned_by'],'pinned_at':x['pinned_at']} for x in rows],'next_cursor':None})
  m=re.fullmatch(r'/api/messages/(\d+)(?:/(.*))?',path)
  if m:
   mid=int(m.group(1)); msg=q('SELECT * FROM messages WHERE id=?',(mid,),True)
   if not msg:return self.send(404,{'error':'message'})
   if not accessible(uid,msg['channel_id']):return self.send(403,{'error':'forbidden'})
   sub=m.group(2)
   if method=='PATCH':
    if msg['deleted']:return self.send(409,{'error':'deleted'})
    if msg['author_id']!=uid:return self.send(403,{'error':'author'})
    b=self.body()
    if not b.get('body'):return self.send(400,{'error':'empty'})
    ex('UPDATE messages SET body=?,edited_at=? WHERE id=?',(b['body'],now(),mid)); mo=msgobj(q('SELECT * FROM messages WHERE id=?',(mid,),True)); emit(msg['channel_id'],'message.updated',{'message':mo}); return self.send(200,{'message':mo})
   if method=='DELETE':
    if msg['author_id']!=uid and member(uid,q('SELECT workspace_id FROM channels WHERE id=?',(msg['channel_id'],),True)['workspace_id'])!='owner':return self.send(403,{'error':'forbidden'})
    if not msg['deleted']:ex('UPDATE messages SET deleted=1 WHERE id=?',(mid,)); emit(msg['channel_id'],'message.deleted',{'message_id':mid})
    return self.send(200,{'deleted':True})
   if method=='GET' and sub=='replies':
    rows=q('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id',(mid,)); return self.send(200,{'replies':[msgobj(x) for x in rows],'next_cursor':None})
   if method=='POST' and sub=='pin': ex('INSERT OR REPLACE INTO pins VALUES(?,?,?)',(mid,uid,now())); return self.send(200,{'pin':{'message_id':mid,'pinned_by':uid,'pinned_at':now()}})
   if method=='DELETE' and sub=='pin':ex('DELETE FROM pins WHERE message_id=?',(mid,));return self.send(200,{'unpinned':True})
   if method=='POST' and sub=='reactions':
    e=self.body().get('emoji',''); ex('INSERT OR IGNORE INTO reactions VALUES(?,?,?)',(mid,uid,e)); return self.send(200,{'reactions':msgobj(q('SELECT * FROM messages WHERE id=?',(mid,),True))['reactions']})
  if path=='/api/search':
   text=qs.get('q',[''])[0]; rows=q('SELECT * FROM messages WHERE deleted=0 AND body LIKE ? ORDER BY id DESC LIMIT 200',('%'+text+'%',)); return self.send(200,{'results':[msgobj(x) for x in rows],'next_cursor':None})
  if path=='/api/dms' and method=='POST':
   other=self.body().get('user_id'); a='dm:'+','.join(map(str,sorted([uid,int(other)]))); w=q('SELECT id FROM workspaces WHERE slug=?',(a,),True)
   if not w:
    wid=ex('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(a,a,uid)); cid=ex('INSERT INTO channels(workspace_id,name,is_dm) VALUES(?,?,1)',(wid,'dm')); ex('INSERT INTO members VALUES(?,?,?)',(wid,uid,'member')); ex('INSERT OR IGNORE INTO members VALUES(?,?,?)',(wid,other,'member')); ex('INSERT INTO channel_members VALUES(?,?)',(cid,uid)); ex('INSERT INTO channel_members VALUES(?,?)',(cid,other))
   else: cid=q('SELECT id FROM channels WHERE workspace_id=?',(w['id'],),True)['id']
   return self.send(200,{'channel_id':cid})
  if path=='/api/read': return self.send(404,{'error':'not found'})
  return self.send(404,{'error':'not found'})
 def do_GET(self): 
  try:self.route()
  except Exception as e:self.send(500,{'error':str(e)})
 def do_POST(self):
  try:self.route()
  except Exception as e:self.send(500,{'error':str(e)})
 def do_PATCH(self):
  try:self.route()
  except Exception as e:self.send(500,{'error':str(e)})
 def do_DELETE(self):
  try:self.route()
  except Exception as e:self.send(500,{'error':str(e)})
 def html(self):
  b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def websocket(self):
  if not auth({'Authorization':'Bearer '+urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query).get('token',[''])[0]}): self.send(401,{}); return
  key=self.headers.get('Sec-WebSocket-Key')
  if not key:return self.send(400,{})
  self.send_response(101,'Switching Protocols');self.send_header('Upgrade','websocket');self.send_header('Connection','Upgrade');self.send_header('Sec-WebSocket-Accept',base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode());self.end_headers()
  s=self.connection; cid=None
  with WSL: WS.add((s,0))
  try:
   while True:
    h=s.recv(2)
    if not h:break
    ln=h[1]&127
    if ln==126:ln=struct.unpack('>H',s.recv(2))[0]
    elif ln==127:ln=struct.unpack('>Q',s.recv(8))[0]
    mask=s.recv(4); data=s.recv(ln); data=bytes(data[i]^mask[i%4] for i in range(ln)); x=json.loads(data)
    if x.get('type') in ('subscribe','resume'):
     cid=int(x['channel_id'])
     with WSL:
      WS.discard((s,0));WS.add((s,cid))
     ev=q('SELECT COALESCE(MAX(event_id),0) n FROM events WHERE channel_id=?',(cid,),True)['n']
     sendws(s,json.dumps({'type':'subscribed' if x['type']=='subscribe' else 'resumed','channel_id':cid,'head_event_id':ev}).encode())
  except:pass
  finally:
   with WSL:WS.discard((s,cid));WS.discard((s,0))
HTML='''<!doctype html><html><head><title>Huddle</title><style>body{margin:0;font-family:Arial;color:#222}button{border:0;padding:9px 14px;color:#fff;border-radius:4px}.primary{background:#007a5a}.danger{background:#e01e5a}.secondary{background:#1264a3}.app{display:flex;height:100vh}.side{width:260px;background:#3f0f40;color:white;padding:20px}.main{flex:1;padding:25px}.msg{padding:12px;border-bottom:1px solid #ddd}</style></head><body><div id="root"></div><script>
const api=(p,o={})=>fetch('/api'+p,{headers:{'Content-Type':'application/json',Authorization:'Bearer '+(localStorage.getItem('huddle.token')||'')},...o}).then(r=>r.json());
function auth(){root.innerHTML='<div data-testid="auth-form"><h1>Huddle</h1><input id="un" name="username"><input id="pw" name="password" type="password"><button class="primary" data-testid="auth-submit" data-button-role="primary">Login</button><button data-testid="auth-toggle">Sign up</button><div id="err"></div></div>';document.querySelector('[data-testid=auth-submit]').onclick=()=>api('/auth/login',{method:'POST',body:JSON.stringify({username:un.value,password:pw.value})}).then(x=>{if(x.token){localStorage.setItem('huddle.token',x.token);app()}else err.textContent='Invalid credentials'})} 
function app(){root.innerHTML='<div class="app"><aside class="side"><h2 data-testid="workspace-header">Huddle</h2><button class="danger" data-testid="logout-btn" data-button-role="danger">Logout</button><div data-testid="channel-list"></div><button class="secondary" data-testid="new-channel-btn">New channel</button></aside><main class="main"><h2 data-testid="channel-title">Welcome</h2><div data-testid="channel-topic"></div><div data-testid="message-list"></div><input data-testid="message-input"><button class="primary" data-testid="send-btn">Send</button></main></div>';document.querySelector('[data-testid=logout-btn]').onclick=()=>{localStorage.removeItem('huddle.token');auth()};api('/workspaces').then(x=>{(x.workspaces||[]).forEach(w=>api('/workspaces/'+w.slug).then(d=>(d.channels||[]).forEach(c=>{let e=document.createElement('button');e.textContent='#'+c.name;e.dataset.testid='channel-entry';e.dataset.channelId=c.id;e.dataset.channelName=c.name;e.onclick=()=>load(c);document.querySelector('[data-testid=channel-list]').append(e)})))})}
function load(c){document.querySelector('[data-testid=channel-title]').textContent='#'+c.name;api('/channels/'+c.id).then(x=>{messageList.innerHTML=(x.messages||[]).map(m=>'<div class="msg" data-testid="message"><b>'+m.author.username+'</b><div data-testid="message-body">'+m.body+'</div></div>').join('')})}let root=document.getElementById('root');localStorage.getItem('huddle.token')?app():auth();
</script></body></html>'''
if __name__=='__main__':
 ThreadingHTTPServer(('127.0.0.1',PORT),H).serve_forever()
PY
cat > /app/start.sh <<'SH'
#!/bin/sh
mkdir -p /var/lib/huddle
python3 - <<'PY'
import sqlite3,os
os.makedirs('/var/lib/huddle',exist_ok=True)
sqlite3.connect('/var/lib/huddle/huddle.db').execute('PRAGMA journal_mode=WAL')
PY
run(){ while :; do "$@"; sleep .5; done; }
