```mswea_bash_command
python3 - <<'PY'
p='/app/server.py'; s=open(p).read()
marker="if __name__=='__main__':\n"
irc=r'''
IRC_NICKS=set()
IRC_LOCK=threading.Lock()
def irc_send(c,line):
 try: c.sendall((line+'\r\n').encode())
 except Exception: pass
def irc_client(c,addr):
 token=None; nick=None; registered=False; buf=b''
 try:
  c.settimeout(300)
  while True:
   data=c.recv(4096)
   if not data: break
   buf+=data
   while b'\r\n' in buf or b'\n' in buf:
    if b'\r\n' in buf: line,buf=buf.split(b'\r\n',1)
    else: line,buf=buf.split(b'\n',1)
    line=line.decode(errors='replace').strip()
    if not line: continue
    parts=line.split(' ',1); cmd=parts[0].upper(); arg=parts[1] if len(parts)>1 else ''
    if cmd=='PASS':
     token=arg.lstrip(':').strip()
     if not q('SELECT 1 FROM tokens WHERE token=?',(token,),True):
      irc_send(c,':huddle 464 * :Password incorrect')
      token=None
    elif cmd=='NICK':
     nn=arg.lstrip(':').strip()
     if not re.fullmatch(r'[A-Za-z0-9_-]{1,30}',nn):
      irc_send(c,':huddle 432 * '+nn+' :Erroneous nickname'); continue
     with IRC_LOCK:
      collision=nn.lower() in {x.lower() for x in IRC_NICKS} and (nick is None or nn.lower()!=nick.lower())
     if collision:
      irc_send(c,':huddle 433 '+(nick or '*')+' '+nn+' :Nickname is already in use'); continue
     if nick:
      with IRC_LOCK: IRC_NICKS.discard(nick)
     nick=nn
     with IRC_LOCK: IRC_NICKS.add(nick)
    elif cmd=='USER':
     if token and nick and not registered:
      u=q('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(token,),True)
      if u:
       registered=True
       for code,text in [('001','Welcome'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle 1.0 oiwsz biklmnop'),('005','CHANTYPES=# PREFIX=(ov)@+ :are supported')]:
        irc_send(c,':huddle '+code+' '+nick+' '+text)
       irc_send(c,':huddle 422 '+nick+' :MOTD File is missing')
    elif cmd=='PING':
     text=arg.lstrip(':').strip()
     irc_send(c,':huddle PONG huddle :'+text)
    elif cmd=='QUIT':
     break
    elif cmd in ('CAP','USER') and not registered:
     pass
    elif cmd not in ('PONG','NOTICE'):
     irc_send(c,':huddle 421 '+(nick or '*')+' '+cmd+' :Unknown command')
 finally:
  if nick:
   with IRC_LOCK: IRC_NICKS.discard(nick)
  try:c.close()
  except Exception:pass
def irc_server():
 srv=socket.socket(socket.AF_INET,socket.SOCK_STREAM); srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv.bind(('0.0.0.0',6667)); srv.listen(100)
 while True:
  c,a=srv.accept(); threading.Thread(target=irc_client,args=(c,a),daemon=True).start()
'''
s=s.replace(marker,irc+"\n"+marker)
s=s.replace("if __name__=='__main__':\n ThreadingHTTPServer(('127.0.0.1',PORT),H).serve_forever()", "if __name__=='__main__':\n if len(sys.argv)>1 and sys.argv[1]=='irc': irc_server()\n else: ThreadingHTTPServer(('127.0.0.1',PORT),H).serve_forever()")
open(p,'w').write(s)
